package com.ibs;
import java.time.*;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
@RestController
@RequestMapping("/api/support/operations")
public class EventReportController {
 private final ServiceDeskController incidents;
 private final Map<String,Map<String,String>> events=new LinkedHashMap<>();
 private boolean autoCreate=false;
 private int sequence=1000;
 public EventReportController(ServiceDeskController incidents){this.incidents=incidents;}
 private void auth(HttpServletRequest r){if(!SupportPortalController.authorized(r))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);}
 private void require(boolean ok,String reason){if(!ok)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,reason);}
 private String field(Map<String,String>b,String k,int max){String v=b.getOrDefault(k,"");require(v!=null&&v.length()<=max,k);return v.trim();}
 @GetMapping("/events") public synchronized Map<String,Object> events(HttpServletRequest r){auth(r);return Map.of("autoCreate",autoCreate,"events",events.values().stream().map(Map::copyOf).toList());}
 @PutMapping("/settings") public synchronized Map<String,Boolean> settings(HttpServletRequest r,@RequestBody Map<String,Boolean>b){auth(r);require(b.get("autoCreate")!=null,"autoCreate required");autoCreate=b.get("autoCreate");return Map.of("autoCreate",autoCreate);}
 @PostMapping("/events") public synchronized Map<String,String> event(HttpServletRequest r,@RequestBody Map<String,String>b){auth(r);String app=field(b,"application",10),rule=field(b,"rule",60),message=field(b,"message",1000),severity=field(b,"severity",10);require(Set.of("IBS","EIMP").contains(app)&&Set.of("Critical","High","Medium","Low").contains(severity)&&!rule.isBlank()&&!message.isBlank(),"Invalid event");Instant now=Instant.now();for(Map<String,String> e:events.values())if(e.get("application").equals(app)&&e.get("rule").equals(rule)&&e.get("severity").equals(severity)&&Instant.parse(e.get("created")).isAfter(now.minusSeconds(300)))return Map.copyOf(e);if(events.size()>=200)throw new ResponseStatusException(HttpStatus.CONFLICT,"Event capacity");Map<String,String> e=new LinkedHashMap<>();e.put("id",String.format("EVT%07d",++sequence));e.put("application",app);e.put("rule",rule);e.put("message",message);e.put("severity",severity);e.put("created",now.toString());e.put("source","SIMULATED");e.put("incident","");long recent=events.values().stream().filter(x->!x.get("incident").isBlank()&&Instant.parse(x.get("created")).isAfter(now.minusSeconds(3600))).count();if(autoCreate&&recent<10&&Set.of("Critical","High").contains(severity)){Map<String,Object> t=incidents.create(r,Map.of("application",app,"title","Simulated alert: "+rule,"description",message,"impact",severity.equals("Critical")?"1":"2","urgency","1","category","Application","requestId",e.get("id")));e.put("incident",t.get("id").toString());}events.put(e.get("id"),e);return Map.copyOf(e);}
 private long elapsed(Map<String,Object> t,String key){return Duration.between(Instant.parse(t.get("created").toString()),Instant.parse(t.get(key).toString())).toSeconds();}
 @GetMapping("/report") public Map<String,Object> report(HttpServletRequest r){auth(r);List<Map<String,Object>> rows=incidents.list(r);Instant now=Instant.now();Map<String,Long> priority=new TreeMap<>(),application=new TreeMap<>();List<String> escalation=new ArrayList<>();long responseBreaches=0,resolutionBreaches=0,responded=0,resolved=0,responseSeconds=0,resolutionSeconds=0;for(Map<String,Object> t:rows){priority.merge(t.get("priority").toString(),1L,Long::sum);application.merge(t.get("application").toString(),1L,Long::sum);boolean rb=t.containsKey("responseDeadline")&&Instant.parse(t.getOrDefault("responded",now.toString()).toString()).isAfter(Instant.parse(t.get("responseDeadline").toString()));boolean sb=Instant.parse(t.getOrDefault("resolved",now.toString()).toString()).isAfter(Instant.parse(t.get("deadline").toString()));if(rb)responseBreaches++;if(sb)resolutionBreaches++;if(t.containsKey("responded")){responded++;responseSeconds+=elapsed(t,"responded");}if(t.containsKey("resolved")){resolved++;resolutionSeconds+=elapsed(t,"resolved");}if(!Set.of("Resolved","Closed").contains(t.get("state"))&&(rb||sb))escalation.add(t.get("id")+" | "+t.get("group")+" | "+(rb?"Response breach ":"")+(sb?"Resolution breach":""));}Map<String,Object> m=new LinkedHashMap<>();m.put("total",rows.size());m.put("byPriority",priority);m.put("byApplication",application);m.put("responseBreaches",responseBreaches);m.put("resolutionBreaches",resolutionBreaches);m.put("mttaSeconds",responded==0?null:responseSeconds/responded);m.put("mttrSeconds",resolved==0?null:resolutionSeconds/resolved);m.put("respondedCount",responded);m.put("resolvedCount",resolved);m.put("escalationQueue",escalation);return m;}
}
